import {createContext, useContext} from 'react';

/** Caption word: script text with ASR or synthetic timing; asterisks mark emphasis. */
export type Word = {text: string; start: number; end: number; accent: boolean; chunk: number};

/** Film props generated by scripts/prep.py. */
export type FilmProps = {
  words: Word[];
  chunks: {first: number; last: number}[];
  /** Named cues map to word-start seconds; scenes depend on cues, not fixed times. */
  cues: Record<string, number>;
  /** Per-frame voice amplitude, zero to one; empty means use word timing for the mouth. */
  amplitude: number[];
  durationInFrames: number;
  audioDuration: number;
  fps?: number;
  /** Optional voice and sound paths inside public/. */
  audio?: string | null;
  sfx?: string | null;
  sfxVolume?: number;
};

export type FilmState = {t: number; frame: number; c: Record<string, number>; p: FilmProps};
export const FilmContext = createContext<FilmState | null>(null);

/** In scenes: const {t,c}=useFilm(); t is seconds and c.name is a cue time. */
export const useFilm = () => {
  const v = useContext(FilmContext);
  if (!v) throw new Error('useFilm() must run inside <Film>');
  return v;
};

const SAFE = new Set(['toJSON', 'then', 'constructor', 'valueOf', 'toString', 'hasOwnProperty']);
/** Throw on missing cues instead of silently producing NaN and invisible scenes. */
export const strictCues = (cues: Record<string, number>) =>
  new Proxy(cues, {
    get(o, k) {
      if (typeof k === 'string' && !(k in o) && !SAFE.has(k)) throw new Error(`Missing cue ${k} in props.cues; add it to cues.json and rerun prep.py`);
      return (o as Record<string | symbol, number>)[k];
    },
  });
